package io.github.astelev.around_planet.gametest;
import io.github.astelev.around_planet.*;
import io.github.astelev.around_planet.client.*;
import io.github.astelev.around_planet.space.*;
import net.minecraft.client.Minecraft;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.neoforge.client.event.ClientTickEvent;
@EventBusSubscriber(modid="around_planet",value=Dist.CLIENT)
public final class LunarSurfaceSkySmoke {
 private static int ticks,phase,start;private static volatile Throwable failure;private static volatile long clock;private static SpaceVector previous;private static int verifiedPhase;private static long verifiedClock;
 @SubscribeEvent public static void tick(ClientTickEvent.Post event){if(!Boolean.getBoolean("around_planet.lunarSkySmoke"))return;var mc=Minecraft.getInstance();if(mc.screen instanceof net.minecraft.client.gui.screens.BackupConfirmScreen){for(var w:mc.screen.children())if(w instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().contains("I know")){b.onPress();return;}}ticks++;if(failure!=null)throw new AssertionError("Lunar sky server fixture",failure);if(ticks>1600)throw new AssertionError("Lunar sky timeout phase="+phase);if(mc.level==null||mc.player==null||mc.getSingleplayerServer()==null||ticks<100)return;
  if(phase==0){phase=1;start=ticks;mc.options.hideGui=true;mc.options.cloudStatus().set(net.minecraft.client.CloudStatus.OFF);server(mc,()->{PlanetConfig.ENABLED.set(true);PlanetConfig.SURFACE_SKY.set(true);PlanetConfig.SURFACE_CURVE.set(true);var level=mc.getSingleplayerServer().overworld();var p=level.players().getFirst();p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.setNoGravity(true);p.getAbilities().flying=true;p.onUpdateAbilities();p.teleportTo(0,300,0);level.setDayTime(18000);level.setWeatherParameters(60000,0,false,false);var data=SpaceOrbitData.get(level.getServer());var sys=data.system();clock=Math.round(sys.period()*20/4)-level.getGameTime();data.system(new CelestialSystem(sys.earthRadius(),sys.earthMu(),clock,sys.earthEntry()));});return;}
  var sys=CelestialSky.current();if(sys==null||sys.clockTicks()!=clock)return;var c=mc.gameRenderer.getMainCamera().getPosition();var world=new SpaceVector(c.x,c.y,c.z);var a=MoonAppearance.at(sys,new PlanetScale(PlanetConfig.PLANET_SIZE.get()).geometry(),PlanetDaylight.spin(mc.level),world,mc.level.getGameTime());look(mc,a.center());if(ticks-start<65||verifiedPhase!=phase||verifiedClock!=clock)return;shot(mc,"surface-orbital-moon-alpha45-"+phase+".png");
  if(phase==1){previous=a.center();phase=2;start=ticks;server(mc,()->{var data=SpaceOrbitData.get(mc.getSingleplayerServer());var model=data.system();clock=model.clockTicks()+Math.round(model.period()*20/8);data.system(new CelestialSystem(model.earthRadius(),model.earthMu(),clock,model.earthEntry()));});}
  else if(phase==2){require(angle(previous,a.center())>.3,"Moon remained opposite the Sun after ephemeris change");previous=a.center();phase=3;start=ticks;server(mc,()->mc.getSingleplayerServer().overworld().players().getFirst().teleportTo(PlanetConfig.PLANET_SIZE.get()/4.0,300,3000));}
  else if(phase==3){require(angle(previous,a.center())>.5,"Moon ignored observer longitude");phase=4;start=ticks;server(mc,()->{var result=SpaceTimeWarp.advance(mc.getSingleplayerServer(),2400);require(result.ticks()==2400,"Empty-world warp was limited");clock=SpaceOrbitData.get(mc.getSingleplayerServer()).system().clockTicks();});}
  else if(phase==4){require(SurfaceRenderState.skyFrames>0,"Custom sky did not draw");SkyContrastGpuSmoke.check();AroundPlanet.LOGGER.info("SURFACE_LUNAR_EPHEMERIS_PASS synchronized shader center/radius, non-opposition orbit, geographic parallax and time warp; clock={}",clock);mc.options.hideGui=false;phase=5;mc.stop();}
 }
 @SubscribeEvent public static void rendered(net.neoforged.neoforge.client.event.RenderLevelStageEvent event){if(!Boolean.getBoolean("around_planet.lunarSkySmoke")||event.getStage()!=net.neoforged.neoforge.client.event.RenderLevelStageEvent.Stage.AFTER_SKY||phase<1||phase>4)return;var mc=Minecraft.getInstance();var sys=CelestialSky.current();if(sys==null||sys.clockTicks()!=clock)return;float partial=event.getPartialTick().getGameTimeDeltaPartialTick(false);var c=event.getCamera().getPosition();var expected=MoonAppearance.at(sys,new PlanetScale(PlanetConfig.PLANET_SIZE.get()).geometry(),PlanetDaylight.spin(mc.level,partial),new SpaceVector(c.x,c.y,c.z),mc.level.getGameTime()+partial);verifyUniforms(mc,expected);verifiedPhase=phase;verifiedClock=clock;}
 private static void verifyUniforms(Minecraft mc,MoonAppearance a){try{var field=SurfaceSkyRenderer.class.getDeclaredField("shader");field.setAccessible(true);var shader=(net.minecraft.client.renderer.ShaderInstance)field.get(null);int center=org.lwjgl.opengl.GL20.glGetUniformLocation(shader.getId(),"MoonCenter"),radius=org.lwjgl.opengl.GL20.glGetUniformLocation(shader.getId(),"MoonRadius");require(center>=0&&radius>=0,"Orbital Moon uniforms were optimized away");float[] value=new float[3];org.lwjgl.opengl.GL20.glGetUniformfv(shader.getId(),center,value);var actual=new SpaceVector(value[0],value[1],value[2]);require(actual.subtract(a.center()).length()/a.center().length()<.00001,"Shader Moon differs from orbital observer coordinates: "+actual+" / "+a.center());require(Math.abs(org.lwjgl.opengl.GL20.glGetUniformf(shader.getId(),radius)-a.radius())<.01,"Shader Moon radius differs from orbit model");}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
 private static double angle(SpaceVector a,SpaceVector b){return Math.acos(Math.clamp(a.dot(b)/(a.length()*b.length()),-1,1));}
 private static void look(Minecraft mc,SpaceVector v){mc.player.setYRot((float)Math.toDegrees(Math.atan2(-v.x(),v.z())));mc.player.setXRot((float)Math.toDegrees(Math.atan2(-v.y(),Math.hypot(v.x(),v.z()))));}
 private static void server(Minecraft mc,Runnable action){mc.getSingleplayerServer().execute(()->{try{action.run();}catch(Throwable t){failure=t;}});}
 private static void shot(Minecraft mc,String name){net.minecraft.client.Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),m->{});}
 private static void require(boolean value,String message){if(!value)throw new AssertionError(message);}
}
